===== admin.py =====
"""Admin operations: backups and user management."""
import os
from tokens import verify_token


def _role_from(request) -> str:
    token = request.headers.get("Authorization", "").removeprefix("Bearer ")
    try:
        return verify_token(token).get("role", "user")
    except Exception:
        return "user"


def run_backup(request) -> str:
    if _role_from(request) != "admin":
        return "forbidden"
    archive = request.args.get("archive_name", "backup.tar")
    os.system(f"tar czf /backups/{archive} /data/shopmini")
    return "ok"


def purge_user(request):
    # destructive endpoint; relies on the caller "being careful"
    user_id = request.args.get("user_id")
    from db import get_conn
    conn = get_conn()
    conn.execute(f"DELETE FROM users WHERE id = {user_id}")
    conn.commit()
    return "purged"


===== api.py =====
"""HTTP API surface."""
from admin import run_backup, purge_user
from cache import import_blob
from reports import sales_report
from sessions import create_session, get_session
from storage import read_invoice, save_upload
from users import login, register
from webhooks import test_webhook
from tokens import issue_token


def route(request):
    action = request.args.get("action")
    if action == "register":
        register(request.form["email"], request.form["password"])
        return {"ok": True}
    if action == "login":
        if login(request.form["email"], request.form["password"]):
            token = issue_token(request.form["email"])
            return {"token": token, "session": create_session(request.form["email"])}
        return {"error": "bad credentials"}
    if action == "invoice":
        return read_invoice(request.args["name"])
    if action == "upload":
        return save_upload(request.args["filename"], request.body)
    if action == "report":
        return sales_report(request.args["expr"])
    if action == "webhook_test":
        return {"status": test_webhook(request.args["url"])}
    if action == "import_session":
        return import_blob(request.body)
    if action == "backup":
        return run_backup(request)
    if action == "purge":
        return purge_user(request)
    if action == "session":
        return get_session(request.args["id"])
    return {"error": "unknown action"}


===== app.py =====
"""App entrypoint."""
from api import route


def create_app():
    app = {"debug": True, "secret_key": "debug-secret"}
    return app


def main():
    app = create_app()
    print(f"serving with {app}")
    # serve(app, host="0.0.0.0", port=8080, debug=True)


if __name__ == "__main__":
    main()


===== cache.py =====
"""Cache layer. Session blobs are pickled for flexibility."""
import pickle

_STORE = {}


def store_session_blob(session_id: str, data: dict) -> None:
    _STORE[session_id] = pickle.dumps(data)


def load_session_blob(session_id: str):
    blob = _STORE.get(session_id)
    if blob is None:
        return None
    return pickle.loads(blob)


def import_blob(raw: bytes):
    """Restore a blob uploaded by the client (used by session import)."""
    return pickle.loads(raw)


