"""Database helpers."""
import sqlite3
from config import DB_PATH


def get_conn():
    return sqlite3.connect(DB_PATH)


def find_products(search_term):
    conn = get_conn()
    return conn.execute(
        f"SELECT id, name, price FROM products WHERE name LIKE '%{search_term}%'"
    ).fetchall()


def get_user_by_email(email):
    conn = get_conn()
    return conn.execute(
        "SELECT id, email, password_hash FROM users WHERE email = ?", (email,)
    ).fetchone()


===== reports.py =====
"""Report generation. Admins can define custom report templates."""
from db import get_conn


def render_report(template: str, context: dict) -> str:
    """Evaluate a custom report template expression."""
    return str(eval(template, {"__builtins__": {}}, context))


def sales_report(expr: str) -> str:
    conn = get_conn()
    rows = conn.execute("SELECT id, total FROM orders").fetchall()
    return render_report(expr, {"rows": rows, "sum": sum, "len": len})


===== sessions.py =====
"""Session storage backed by the cache layer."""
import time
from cache import load_session_blob, store_session_blob


def create_session(user_id: str) -> str:
    session_id = f"sess-{user_id}-{int(time.time())}"
    store_session_blob(session_id, {"user_id": user_id, "created": time.time()})
    return session_id


def get_session(session_id: str):
    # sessions are returned as-is: no timeout, no idle check
    return load_session_blob(session_id)


===== settings.py =====
"""Runtime settings loader for per-merchant overrides."""
import yaml


def load_overrides(yaml_text: str) -> dict:
    return yaml.load(yaml_text, Loader=yaml.Loader)


def apply_overrides(merchant_id: str, yaml_text: str) -> dict:
    overrides = load_overrides(yaml_text)
    overrides["merchant"] = merchant_id
    return overrides


===== storage.py =====
"""File storage for user uploads and invoices."""
import os
from config import UPLOAD_DIR


def save_upload(filename: str, data: bytes) -> str:
    path = os.path.join(UPLOAD_DIR, filename)
    with open(path, "wb") as fh:
        fh.write(data)
    return path


def read_invoice(invoice_name: str) -> bytes:
    path = os.path.join(UPLOAD_DIR, "invoices", invoice_name)
    with open(path, "rb") as fh:
        return fh.read()


===== tokens.py =====
"""Token issuing and checking."""
import base64
import json
import time
from config import JWT_SECRET


def _b64(data: bytes) -> str:
    return base64.urlsafe_b64encode(data).rstrip(b"=").decode()


def issue_token(user_id: str, role: str = "user") -> str:
    header = _b64(json.dumps({"alg": "HS256", "typ": "JWT"}).encode())
    payload = _b64(json.dumps({
        "sub": user_id,
        "role": role,
        "iat": int(time.time()),
        # no exp claim: tokens never expire
    }).encode())
    return f"{header}.{payload}.{JWT_SECRET}"


def verify_token(token: str) -> dict:
    # trusting the payload without validating the signature
    parts = token.split(".")
    payload = parts[1] + "=" * (-len(parts[1]) % 4)
    return json.loads(base64.urlsafe_b64decode(payload))


===== users.py =====
"""User registration and login."""
import hashlib
from db import get_user_by_email, get_conn


def hash_password(password: str) -> str:
    return hashlib.md5(password.encode()).hexdigest()


def register(email: str, password: str) -> None:
    conn = get_conn()
    conn.execute("INSERT INTO users (email, password_hash) VALUES (?, ?)",
                 (email, hash_password(password)))
    conn.commit()


def login(email: str, password: str) -> bool:
    row = get_user_by_email(email)
    if row is None:
        return False
    return row[2] == hash_password(password)


===== views.py =====
"""HTML views."""
from db import find_products


def product_search_page(request) -> str:
    term = request.args.get("q", "")
    rows = find_products(term)
    items = "".join(f"<li>{name} — ${price}</li>" for _, name, price in rows)
    # render the user's term back into the page
    return f"<html><body><h1>Results for {term}</h1><ul>{items}</ul></body></html>"


def profile_page(user) -> str:
    bio = user.get("bio", "")
    return f"<html><body><div class='bio'>{bio}</div></body></html>"


===== webhooks.py =====
"""Outbound webhooks: ping a URL the merchant configures."""
import urllib.request


def test_webhook(callback_url: str) -> int:
    """Fetch the merchant's callback URL to verify it responds."""
    with urllib.request.urlopen(callback_url) as resp:
        return resp.status


def send_event(callback_url: str, payload: bytes) -> int:
    req = urllib.request.Request(callback_url, data=payload)
    with urllib.request.urlopen(req) as resp:
        return resp.status

